INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7703844, 1265138, 30861, '<td valign="top">This is lovely, but it''s barely about the reflections IMO...</td>', 'This is lovely, but it''s barely about the reflections IMO...', '2021-10-20 01:38:59.000000', NULL, 1),
(7703848, 1265107, 126903, '<td valign="top">would love to have seen this in colour</td>', 'would love to have seen this in colour', '2021-10-20 02:38:19.000000', NULL, 1),
(7703849, 1264977, 126903, '<td valign="top">beautiful and tranquil</td>', 'beautiful and tranquil', '2021-10-20 02:40:47.000000', NULL, 1),
(7703863, 1265015, 114285, '<td valign="top">Superb!

<br/>
<br/>A ribbon.</td>', 'Superb!


A ribbon.', '2021-10-20 09:03:04.000000', NULL, 1),
(7703903, 1265010, 67258, '<td valign="top">A pleasing study of the reflection of light on water.</td>', 'A pleasing study of the reflection of light on water.', '2021-10-20 13:12:49.000000', NULL, 1),
(7703904, 1264884, 67258, '<td valign="top">Calm water has given you a good reflection of this water bird.  I wonder if there was the scope for a slightly different view point, or if hanging around longer would have given you the chance to capture the bird facing the viewer, or at least in full profile rather than slightly turned away.</td>', 'Calm water has given you a good reflection of this water bird.  I wonder if there was the scope for a slightly different view point, or if hanging around longer would have given you the chance to capture the bird facing the viewer, or at least in full profile rather than slightly turned away.', '2021-10-20 13:15:06.000000', NULL, 1),
(7703905, 1264897, 67258, '<td valign="top">I like your composition, with the reflection providing all the environmental context.  A shame that the whites have blown.</td>', 'I like your composition, with the reflection providing all the environmental context.  A shame that the whites have blown.', '2021-10-20 13:15:54.000000', NULL, 1),
(7703906, 1265147, 67258, '<td valign="top">Reflection interrupted.  I do like this graphic representation of the challenge.</td>', 'Reflection interrupted.  I do like this graphic representation of the challenge.', '2021-10-20 13:16:38.000000', NULL, 1),
(7703907, 1264975, 67258, '<td valign="top">The flipping of the image makes for a striking image - a shame that the subject within the reflection doesn''t carry more intrinsic interest (at least, for me), but you have done a good job with what you had.</td>', 'The flipping of the image makes for a striking image - a shame that the subject within the reflection doesn''t carry more intrinsic interest (at least, for me), but you have done a good job with what you had.', '2021-10-20 13:18:13.000000', NULL, 1),
(7703908, 1265020, 67258, '<td valign="top">A different take on the challenge (and I''m sure some will consider it somewhat obtuse)  - with some subtle physical reflections for those of a literal mind.  I like the lead-in of the footsteps, used here to hint towards solitude and quiet personal reflection.  The single figure, in a dress or gown, hints towards Buddhism.  Overall, a well considered image.</td>', 'A different take on the challenge (and I''m sure some will consider it somewhat obtuse)  - with some subtle physical reflections for those of a literal mind.  I like the lead-in of the footsteps, used here to hint towards solitude and quiet personal reflection.  The single figure, in a dress or gown, hints towards Buddhism.  Overall, a well considered image.', '2021-10-20 13:21:06.000000', NULL, 1),
(7703910, 1265140, 67258, '<td valign="top">A busy scene that needs the viewer to spend some time studying.  My favourite part is the more peaceful left side of the frame, but the right hand side is fighting for attention and, for me at least, doesn''t marry with your title.</td>', 'A busy scene that needs the viewer to spend some time studying.  My favourite part is the more peaceful left side of the frame, but the right hand side is fighting for attention and, for me at least, doesn''t marry with your title.', '2021-10-20 13:26:06.000000', NULL, 1),
(7703911, 1264955, 67258, '<td valign="top">A tad under exposed, but a pleasing scene nonetheless.</td>', 'A tad under exposed, but a pleasing scene nonetheless.', '2021-10-20 13:26:40.000000', NULL, 1),
(7703912, 1265161, 67258, '<td valign="top">A good reflection in this pleasing scene.  the composition does seem a little cramped, and I suspect that image quality has suffered trying to get so much detail into a 1200px image.</td>', 'A good reflection in this pleasing scene.  the composition does seem a little cramped, and I suspect that image quality has suffered trying to get so much detail into a 1200px image.', '2021-10-20 13:27:58.000000', NULL, 1),
(7703913, 1264960, 67258, '<td valign="top">A standard, pleasingly composed harbour scene.</td>', 'A standard, pleasingly composed harbour scene.', '2021-10-20 13:29:02.000000', NULL, 1),
(7703914, 1265107, 67258, '<td valign="top">Very cool image, and perfect for a mono conversion, which you have handled well.  You have taken me in to another world, not just from your location (Cuba?) but also through your low point of view and perspective.</td>', 'Very cool image, and perfect for a mono conversion, which you have handled well.  You have taken me in to another world, not just from your location (Cuba?) but also through your low point of view and perspective.', '2021-10-20 13:30:31.000000', NULL, 1),
(7703916, 1264914, 67258, '<td valign="top">A very good example of a puddle reflection - well composed, interesting scene, good exposure with tricky night time light.</td>', 'A very good example of a puddle reflection - well composed, interesting scene, good exposure with tricky night time light.', '2021-10-20 13:36:14.000000', NULL, 1),
(7703917, 1265057, 67258, '<td valign="top">Certainly arouses the viewer''s curiosity, but at the end of the day, doesn''t provide enough interest to counter the dull reflection.</td>', 'Certainly arouses the viewer''s curiosity, but at the end of the day, doesn''t provide enough interest to counter the dull reflection.', '2021-10-20 13:37:26.000000', NULL, 1),
(7703918, 1264990, 67258, '<td valign="top">A good reflection, but so over-exposed that most of the dog''s face is completely blown.</td>', 'A good reflection, but so over-exposed that most of the dog''s face is completely blown.', '2021-10-20 13:38:45.000000', NULL, 1),
(7703922, 1265077, 67258, '<td valign="top">I like your simple title - suits the image.  That said, of course, I don''t know which aspect of the composition is motif Mk 1 - I look forward to seeing it reappearing in subsequent challenges.  The focus seems a tad soft, either through a too shallow depth of field, through a lack of sharpening on resizing, or through having to save at too low a resolution to meet the 1200px limit.  I do rather wish that the reflection had a bit more contrast - some selective masking would have helped with that, but its your image, and your choice.</td>', 'I like your simple title - suits the image.  That said, of course, I don''t know which aspect of the composition is motif Mk 1 - I look forward to seeing it reappearing in subsequent challenges.  The focus seems a tad soft, either through a too shallow depth of field, through a lack of sharpening on resizing, or through having to save at too low a resolution to meet the 1200px limit.  I do rather wish that the reflection had a bit more contrast - some selective masking would have helped with that, but its your image, and your choice.', '2021-10-20 14:50:14.000000', NULL, 1),
(7703923, 1264880, 67258, '<td valign="top">I like this very much - bags of instant impact.  I love the Van Gogh tones combined with the Van Gogh waves and brush strokes.</td>', 'I like this very much - bags of instant impact.  I love the Van Gogh tones combined with the Van Gogh waves and brush strokes.', '2021-10-20 14:51:02.000000', NULL, 1),
(7703924, 1265058, 67258, '<td valign="top">A simple, pleasing scene.  There isn''t enough in the composition to hold my interest for long, and so not a high mark, but nonetheless a photo I am glad I viewed.</td>', 'A simple, pleasing scene.  There isn''t enough in the composition to hold my interest for long, and so not a high mark, but nonetheless a photo I am glad I viewed.', '2021-10-20 14:52:51.000000', NULL, 1),
(7703925, 1265145, 67258, '<td valign="top">A pleasing and interesting scene.  the bright and vibrant architecture works very well, although personally I would prefer a little more contrast in the reflections.  Detail seems to be lost the further into the scene the eye travels, which is a shame.</td>', 'A pleasing and interesting scene.  the bright and vibrant architecture works very well, although personally I would prefer a little more contrast in the reflections.  Detail seems to be lost the further into the scene the eye travels, which is a shame.', '2021-10-20 14:55:10.000000', NULL, 1),
(7703926, 1264852, 67258, '<td valign="top">A quiet and gentle image with a title that suits perfectly.  Very pleasingly done.</td>', 'A quiet and gentle image with a title that suits perfectly.  Very pleasingly done.', '2021-10-20 14:56:14.000000', NULL, 1),
(7703927, 1265135, 67258, '<td valign="top">The specular highlights combined with the back-lighting of the ducks make for a striking image.</td>', 'The specular highlights combined with the back-lighting of the ducks make for a striking image.', '2021-10-20 14:57:42.000000', NULL, 1),
(7703928, 1265146, 67258, '<td valign="top">Vibrant and interesting, an abstract composition that holds my interest and makes me wonder about the scene that is being reflected.</td>', 'Vibrant and interesting, an abstract composition that holds my interest and makes me wonder about the scene that is being reflected.', '2021-10-20 14:58:42.000000', NULL, 1),
(7703929, 1265015, 67258, '<td valign="top">Very nicely observed.  I don''t know this bird - an egret or heron of some sort, I think.  There is very little plumage detail, and I don''t know if that is simply a quirk of this particular bird, or if a bit too much noise reduction has been used.  the swirls in the water fill the negative space well.</td>', 'Very nicely observed.  I don''t know this bird - an egret or heron of some sort, I think.  There is very little plumage detail, and I don''t know if that is simply a quirk of this particular bird, or if a bit too much noise reduction has been used.  the swirls in the water fill the negative space well.', '2021-10-20 15:01:07.000000', NULL, 1),
(7703930, 1265115, 67258, '<td valign="top">Your title sums up the sense that he viewer gets.  well observed.</td>', 'Your title sums up the sense that he viewer gets.  well observed.', '2021-10-20 15:01:38.000000', NULL, 1),
(7703931, 1265131, 67258, '<td valign="top">It really does look as though the fence is suspended in space!  An interesting study in light.</td>', 'It really does look as though the fence is suspended in space!  An interesting study in light.', '2021-10-20 15:02:19.000000', NULL, 1),
(7703932, 1265155, 67258, '<td valign="top">Both inverted and tilted - certainly makes the viewer stop and look.  A strong and striking image, but I find it quite hard to view - nothing to rest my eye on, I find myself hunting around the frame and not settling to take in the whole.  Not massively keen on your toning, but that is very much a personal thing.</td>', 'Both inverted and tilted - certainly makes the viewer stop and look.  A strong and striking image, but I find it quite hard to view - nothing to rest my eye on, I find myself hunting around the frame and not settling to take in the whole.  Not massively keen on your toning, but that is very much a personal thing.', '2021-10-20 15:04:28.000000', NULL, 1),
(7703933, 1265157, 67258, '<td valign="top">An interesting shape, but at the end of the day not enough to hold my attention.</td>', 'An interesting shape, but at the end of the day not enough to hold my attention.', '2021-10-20 15:05:46.000000', NULL, 1),
(7703934, 1264965, 67258, '<td valign="top">There. seems to be a bit of a colour cast here, as though the white balance is a tad off.  A pleasing scene, simply presented.</td>', 'There. seems to be a bit of a colour cast here, as though the white balance is a tad off.  A pleasing scene, simply presented.', '2021-10-20 15:06:45.000000', NULL, 1),
(7703936, 1265134, 67258, '<td valign="top">Bold and striking, with immediate grab appeal.</td>', 'Bold and striking, with immediate grab appeal.', '2021-10-20 15:07:31.000000', NULL, 1),
(7703937, 1264999, 67258, '<td valign="top">Very pleasing, with lovely tones and lots of detail throughout.</td>', 'Very pleasing, with lovely tones and lots of detail throughout.', '2021-10-20 15:08:08.000000', NULL, 1),
(7703938, 1265104, 67258, '<td valign="top">Ha!  A nice play of lights.</td>', 'Ha!  A nice play of lights.', '2021-10-20 15:08:35.000000', NULL, 1),
(7703940, 1265121, 67258, '<td valign="top">Good find!  A shame it isn''t a tad sharper, but still a good image.  the off-centre composition is very good.

<br/>As an aside, causes me to remember dr.achoo - he lost a camera taking a similar photo.</td>', 'Good find!  A shame it isn''t a tad sharper, but still a good image.  the off-centre composition is very good.

As an aside, causes me to remember dr.achoo - he lost a camera taking a similar photo.', '2021-10-20 15:10:49.000000', NULL, 1),
(7703941, 1264913, 67258, '<td valign="top">On first look I really liked this -I still do, but with reservations.  You appear to have used a polariser, with the lake bed visible, yet the mountain scene is well reflected - causing my brain to malfunction :)</td>', 'On first look I really liked this -I still do, but with reservations.  You appear to have used a polariser, with the lake bed visible, yet the mountain scene is well reflected - causing my brain to malfunction :)', '2021-10-20 15:12:46.000000', NULL, 1),
(7703942, 1265143, 67258, '<td valign="top">An interesting and very well seen image.</td>', 'An interesting and very well seen image.', '2021-10-20 15:13:34.000000', NULL, 1),
(7703981, 1264955, 114285, '<td valign="top">Stunning scene! I''m sure it was a wonder to behold, should do well.</td>', 'Stunning scene! I''m sure it was a wonder to behold, should do well.', '2021-10-21 01:34:10.000000', NULL, 1),
(7703982, 1265122, 114285, '<td valign="top">Stunning colours, ribbon for you I feel.</td>', 'Stunning colours, ribbon for you I feel.', '2021-10-21 02:07:44.000000', NULL, 1),
(7703986, 1265069, 67258, '<td valign="top">A pleasing study of colour and texture.</td>', 'A pleasing study of colour and texture.', '2021-10-21 04:48:43.000000', NULL, 1),
(7704238, 1265137, 28742, '<td valign="top">A seagull. A seagull lurks above. :P Great image. 8</td>', 'A seagull. A seagull lurks above. :P Great image. 8', '2021-10-22 18:17:33.000000', NULL, 1),
(7704239, 1265107, 28742, '<td valign="top">Reminds me of my view of Tijuana the morning after, but it was much fuzzier. ;) Great work!</td>', 'Reminds me of my view of Tijuana the morning after, but it was much fuzzier. ;) Great work!', '2021-10-22 18:19:16.000000', NULL, 1),
(7704240, 1265122, 28742, '<td valign="top">Hey, I thought Dodos were extinct! ...oh yeah, "archival" - you musta reached WAAAYYY back. :P This is a ten from me.</td>', 'Hey, I thought Dodos were extinct! ...oh yeah, "archival" - you musta reached WAAAYYY back. :P This is a ten from me.', '2021-10-22 18:20:58.000000', NULL, 1),
(7704257, 1265015, 122678, '<td valign="top">This is my favorite image for this challenge. It is a beautiful and delicate image, as well as a very special capture.</td>', 'This is my favorite image for this challenge. It is a beautiful and delicate image, as well as a very special capture.', '2021-10-22 20:54:25.000000', NULL, 1),
(7704258, 1265150, 122678, '<td valign="top">Stunning, one of my top 3.</td>', 'Stunning, one of my top 3.', '2021-10-22 20:54:50.000000', NULL, 1),
(7704261, 1264885, 122678, '<td valign="top">This is beautiful moment, a perfect reflection like a mirror. Both the shot and the reflection are crisp and clear.

<br/>Perfect</td>', 'This is beautiful moment, a perfect reflection like a mirror. Both the shot and the reflection are crisp and clear.

Perfect', '2021-10-22 20:59:14.000000', NULL, 1),
(7704283, 1265015, 91360, '<td valign="top">amazing reflection! the eye in the reflection is even more sharp.</td>', 'amazing reflection! the eye in the reflection is even more sharp.', '2021-10-23 03:21:12.000000', NULL, 1),
(7704284, 1264880, 91360, '<td valign="top">wonder! like a paint!10.</td>', 'wonder! like a paint!10.', '2021-10-23 03:22:21.000000', NULL, 1),
(7704366, 1265015, 66597, '<td valign="top">Absolutely beautiful. Bumping to a 9.</td>', 'Absolutely beautiful. Bumping to a 9.', '2021-10-24 10:47:09.000000', NULL, 1),
(7704367, 1265107, 66597, '<td valign="top">Wonderful street photo. Tells a little story.</td>', 'Wonderful street photo. Tells a little story.', '2021-10-24 10:47:34.000000', NULL, 1),
(7704368, 1264885, 66597, '<td valign="top">What a capture! Although I find the background behind the squirrel such a touch bright, this is great. 8.</td>', 'What a capture! Although I find the background behind the squirrel such a touch bright, this is great. 8.', '2021-10-24 10:48:24.000000', NULL, 1),
(7704369, 1265020, 66597, '<td valign="top">I really like the moodiness of this photo.</td>', 'I really like the moodiness of this photo.', '2021-10-24 10:48:44.000000', NULL, 1),
(7704370, 1265155, 66597, '<td valign="top">Really cool perspective and great upside-down flip</td>', 'Really cool perspective and great upside-down flip', '2021-10-24 10:49:14.000000', NULL, 1),
(7704371, 1264977, 66597, '<td valign="top">Very pretty</td>', 'Very pretty', '2021-10-24 10:49:21.000000', NULL, 1),
(7704386, 1264865, 67258, '<td valign="top">An excellent ''puddle'' reflection.</td>', 'An excellent ''puddle'' reflection.', '2021-10-24 14:07:15.000000', NULL, 1),
(7704387, 1264977, 67258, '<td valign="top">Very pretty and tranquil.  My only slight quibble is with the tallest mast - as my eyes followed it up, I hit the top of the frame with a bit of a bump.</td>', 'Very pretty and tranquil.  My only slight quibble is with the tallest mast - as my eyes followed it up, I hit the top of the frame with a bit of a bump.', '2021-10-24 14:08:23.000000', NULL, 1),
(7704388, 1265056, 67258, '<td valign="top">Cool - the patterns created by the ripples certainly make for an interesting study.  Personally, I prefer the scene with the very to section cropped away, from about 2/3rds up the shortest post.  For me all the interest is in the rippled reflections, and the busy jumble of boats takes away the impact.</td>', 'Cool - the patterns created by the ripples certainly make for an interesting study.  Personally, I prefer the scene with the very to section cropped away, from about 2/3rds up the shortest post.  For me all the interest is in the rippled reflections, and the busy jumble of boats takes away the impact.', '2021-10-24 14:11:12.000000', NULL, 1),
(7704389, 1265138, 67258, '<td valign="top">What lovely scene.  I''m not sure about the toning - possibly like that in reality from a mixture of pollution and sodium lighting?  I rather like the lack of detail, like a painting - pretty sure the is an intentional choice on the part of the author.</td>', 'What lovely scene.  I''m not sure about the toning - possibly like that in reality from a mixture of pollution and sodium lighting?  I rather like the lack of detail, like a painting - pretty sure the is an intentional choice on the part of the author.', '2021-10-24 14:13:00.000000', NULL, 1),
(7704390, 1265082, 67258, '<td valign="top">Looks like a lovely place to spend an afternoon.  Here the bright sun has not done you any favours - in particular, the burnt highlights just above centre are quite distracting.</td>', 'Looks like a lovely place to spend an afternoon.  Here the bright sun has not done you any favours - in particular, the burnt highlights just above centre are quite distracting.', '2021-10-24 14:14:18.000000', NULL, 1),
(7704391, 1265136, 67258, '<td valign="top">When I first viewed this on my work monitor (lunch break, honest) I decided not to vote, but to look again on my calibrated home monitor.  I still find myself conflicted.  What I love - the sense of mystery, of another world, and the way it could come from any era; I especially love the mysterious, possibly nefarious figure on the bridge - fascinating.  What I am not so keen on - the large area of black that carries no detail the I can discern.  Nonetheless, a 7 from me.</td>', 'When I first viewed this on my work monitor (lunch break, honest) I decided not to vote, but to look again on my calibrated home monitor.  I still find myself conflicted.  What I love - the sense of mystery, of another world, and the way it could come from any era; I especially love the mysterious, possibly nefarious figure on the bridge - fascinating.  What I am not so keen on - the large area of black that carries no detail the I can discern.  Nonetheless, a 7 from me.', '2021-10-24 14:18:24.000000', NULL, 1),
(7704392, 1265132, 67258, '<td valign="top">A very pretty scene, well captured.  I do, though, rather wish the the figure in red was captured to the side (and ideally, in this instance, on the third).  The red is so bold that it continually draws my eye back in to the centre.</td>', 'A very pretty scene, well captured.  I do, though, rather wish the the figure in red was captured to the side (and ideally, in this instance, on the third).  The red is so bold that it continually draws my eye back in to the centre.', '2021-10-24 14:20:16.000000', NULL, 1),
(7704393, 1265156, 67258, '<td valign="top">Absolutely completely and utterly stunningly gorgeous.  This must be printed and framed.</td>', 'Absolutely completely and utterly stunningly gorgeous.  This must be printed and framed.', '2021-10-24 14:21:13.000000', NULL, 1),
(7704394, 1265122, 67258, '<td valign="top">What an amazing bird, and so well photographed.  Shame about the fairly high level of noise - might be worth trying out Topaz deNoise.</td>', 'What an amazing bird, and so well photographed.  Shame about the fairly high level of noise - might be worth trying out Topaz deNoise.', '2021-10-24 14:22:22.000000', NULL, 1),
(7704395, 1264812, 67258, '<td valign="top">You have captured the lights of the city reflected in the water well.  Not so keen on the converging verticals.</td>', 'You have captured the lights of the city reflected in the water well.  Not so keen on the converging verticals.', '2021-10-24 14:23:20.000000', NULL, 1),
(7704396, 1265124, 67258, '<td valign="top">That sunset must have been amazing!  I particularly like how the light reflected on the water shows the pattern of the currents and water movement.</td>', 'That sunset must have been amazing!  I particularly like how the light reflected on the water shows the pattern of the currents and water movement.', '2021-10-24 14:25:03.000000', NULL, 1),
(7704397, 1265150, 67258, '<td valign="top">Cracking reflection, very well captured.I particularly like the way the foreground rocks mirror the converging clouds in the sky, all leading the eye to the hills and their reflection.  Very nicely done.

<br/>As an aside, you have some sensor dust that you could do with cloning out before you print this for your wall.  bumping to 9</td>', 'Cracking reflection, very well captured.I particularly like the way the foreground rocks mirror the converging clouds in the sky, all leading the eye to the hills and their reflection.  Very nicely done.

As an aside, you have some sensor dust that you could do with cloning out before you print this for your wall.  bumping to 9', '2021-10-24 14:25:15.000000', NULL, 1),
(7704398, 1265151, 67258, '<td valign="top">Beautifully observed - I really like this very much. Bumping to 9.</td>', 'Beautifully observed - I really like this very much. Bumping to 9.', '2021-10-24 14:25:26.000000', NULL, 1),
(7704399, 1265137, 67258, '<td valign="top">Spot on for the challenge.  A Sandpiper of some sort?  At any rate, from the Tringa family, and beautifully captured.  The inclusion of the looming gull works really well for this challenge, although I am certain the as a stand-alone photo I would prefer it with clear negative space.  In my top 5.</td>', 'Spot on for the challenge.  A Sandpiper of some sort?  At any rate, from the Tringa family, and beautifully captured.  The inclusion of the looming gull works really well for this challenge, although I am certain the as a stand-alone photo I would prefer it with clear negative space.  In my top 5.', '2021-10-24 14:25:48.000000', NULL, 1),
